// Command frozengen freezes a release's signed entries for the cross-version
// test in frozen_test.go.
//
// The point of the frozen set is that it does not move with the code: the
// entries are signed by an earlier release and committed under
// testdata/frozen/<release>/, and the current library must keep verifying,
// inspecting and re-encoding them exactly as they were. It is deliberately kept
// away from testdata/vectors, which is regenerated by every `make vectors`; a
// set that moved with the generator would prove nothing about the old release.
//
// This command only uses API that existed in v0.1.0 (Preimage, Payload,
// AuthorizeEntry, WithDelegates, Inspect, NewEd25519Signer, ForAddress,
// ParseAddress), so it compiles and runs against any release from v0.1.0 on.
// To freeze a new release, from a clean checkout of the current repository:
//
//	git worktree add /tmp/soroauth-<release> <release>
//	cp -r scripts/frozengen /tmp/soroauth-<release>/cmd/frozengen
//	(cd /tmp/soroauth-<release> && \
//	   go run ./cmd/frozengen --release <release> --out "$OLDPWD/testdata/frozen/<release>")
//
// The generated files are committed together with the release they came from,
// and the copy of this command under cmd/ in that worktree is not committed.
package main

import (
	"context"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"flag"
	"fmt"
	"math"
	"os"
	"path/filepath"

	soroauth "github.com/soroauth/soroauth-go"
	"github.com/stellar/go-stellar-sdk/keypair"
	"github.com/stellar/go-stellar-sdk/network"
	"github.com/stellar/go-stellar-sdk/strkey"
	"github.com/stellar/go-stellar-sdk/xdr"
)

// validUntilLedger is the expiration the release signs over; it is written into
// the entry and recorded, so the test rebuilds the payload with the same value.
// It parallels the golden vectors' fixed ledger.
const validUntilLedger = uint32(1234567)

// frozenEntry is one committed entry and the release's expected results for it.
// The fields mirror the golden vectors where they overlap, so the two schemes
// read the same way; inspect holds the release's own Inspect JSON.
type frozenEntry struct {
	Name              string          `json:"name"`
	SourceRelease     string          `json:"source_release"`
	NetworkPassphrase string          `json:"network_passphrase"`
	ValidUntilLedger  uint32          `json:"valid_until_ledger"`
	SignedEntryXDR    string          `json:"signed_entry_xdr"`
	PreimageXDR       string          `json:"preimage_xdr"`
	PayloadHex        string          `json:"payload_hex"`
	Inspect           json.RawMessage `json:"inspect"`
}

func main() {
	if err := run(); err != nil {
		fmt.Fprintf(os.Stderr, "frozengen: %v\n", err)
		os.Exit(1)
	}
}

func run() error {
	release := flag.String("release", "v0.1.0", "release tag the entries are signed by")
	out := flag.String("out", "", "directory to write the frozen entries into")
	flag.Parse()
	if *out == "" {
		return fmt.Errorf("--out is required")
	}

	cases := []struct {
		name  string
		build func() (xdr.SorobanAuthorizationEntry, error)
	}{
		{"address", func() (xdr.SorobanAuthorizationEntry, error) { return signAddress(42) }},
		{"address_v2", func() (xdr.SorobanAuthorizationEntry, error) { return signAddressV2(math.MinInt64) }},
		{"delegates_nested", signDelegates},
	}

	if err := os.MkdirAll(*out, 0o755); err != nil {
		return fmt.Errorf("creating %s: %w", *out, err)
	}

	for _, c := range cases {
		entry, err := c.build()
		if err != nil {
			return fmt.Errorf("building %s: %w", c.name, err)
		}
		recorded, err := record(*release, "v0_1_0_"+c.name, entry)
		if err != nil {
			return fmt.Errorf("recording %s: %w", c.name, err)
		}
		raw, err := json.MarshalIndent(recorded, "", "  ")
		if err != nil {
			return fmt.Errorf("marshalling %s: %w", c.name, err)
		}
		raw = append(raw, '\n')
		path := filepath.Join(*out, "v0_1_0_"+c.name+".json")
		if err := os.WriteFile(path, raw, 0o644); err != nil {
			return fmt.Errorf("writing %s: %w", path, err)
		}
		fmt.Printf("wrote %s\n", path)
	}
	return nil
}

// record computes the release's expected results for a signed entry.
func record(release, name string, entry xdr.SorobanAuthorizationEntry) (frozenEntry, error) {
	signed, err := entry.MarshalBinary()
	if err != nil {
		return frozenEntry{}, fmt.Errorf("marshalling entry: %w", err)
	}
	preimage, err := soroauth.Preimage(entry, validUntilLedger, network.TestNetworkPassphrase)
	if err != nil {
		return frozenEntry{}, fmt.Errorf("preimage: %w", err)
	}
	rawPreimage, err := preimage.MarshalBinary()
	if err != nil {
		return frozenEntry{}, fmt.Errorf("marshalling preimage: %w", err)
	}
	payload, err := soroauth.Payload(preimage)
	if err != nil {
		return frozenEntry{}, fmt.Errorf("payload: %w", err)
	}
	info, err := soroauth.Inspect(entry)
	if err != nil {
		return frozenEntry{}, fmt.Errorf("inspect: %w", err)
	}
	inspect, err := json.Marshal(info)
	if err != nil {
		return frozenEntry{}, fmt.Errorf("marshalling inspect: %w", err)
	}

	return frozenEntry{
		Name:              name,
		SourceRelease:     release,
		NetworkPassphrase: network.TestNetworkPassphrase,
		ValidUntilLedger:  validUntilLedger,
		SignedEntryXDR:    base64.StdEncoding.EncodeToString(signed),
		PreimageXDR:       base64.StdEncoding.EncodeToString(rawPreimage),
		PayloadHex:        hex.EncodeToString(payload[:]),
		Inspect:           inspect,
	}, nil
}

// signAddress builds and signs the legacy arm.
func signAddress(nonce int64) (xdr.SorobanAuthorizationEntry, error) {
	kp, err := keypairFor("frozen-v0-1-0-address")
	if err != nil {
		return xdr.SorobanAuthorizationEntry{}, err
	}
	credentials, err := addressCredentials(kp.Address(), nonce)
	if err != nil {
		return xdr.SorobanAuthorizationEntry{}, err
	}
	entry, err := signedBase(xdr.SorobanCredentials{Type: xdr.SorobanCredentialsTypeSorobanCredentialsAddress, Address: &credentials})
	if err != nil {
		return xdr.SorobanAuthorizationEntry{}, err
	}
	return soroauth.AuthorizeEntry(context.Background(), entry, soroauth.NewEd25519Signer(kp), validUntilLedger, network.TestNetworkPassphrase)
}

// signAddressV2 builds and signs the V2 arm. The nonce is the caller's, so the
// set pins the int64 boundary the JSON round-trip is most likely to move.
func signAddressV2(nonce int64) (xdr.SorobanAuthorizationEntry, error) {
	kp, err := keypairFor("frozen-v0-1-0-address-v2")
	if err != nil {
		return xdr.SorobanAuthorizationEntry{}, err
	}
	credentials, err := addressCredentials(kp.Address(), nonce)
	if err != nil {
		return xdr.SorobanAuthorizationEntry{}, err
	}
	entry, err := signedBase(xdr.SorobanCredentials{Type: xdr.SorobanCredentialsTypeSorobanCredentialsAddressV2, AddressV2: &credentials})
	if err != nil {
		return xdr.SorobanAuthorizationEntry{}, err
	}
	return soroauth.AuthorizeEntry(context.Background(), entry, soroauth.NewEd25519Signer(kp), validUntilLedger, network.TestNetworkPassphrase)
}

// signDelegates builds the delegates arm with a two-level nested chain and
// signs every node, so the current library has a fully signed tree to verify.
func signDelegates() (xdr.SorobanAuthorizationEntry, error) {
	top, err := keypairFor("frozen-v0-1-0-delegates-top")
	if err != nil {
		return xdr.SorobanAuthorizationEntry{}, err
	}
	d1, err := keypairFor("frozen-v0-1-0-delegates-d1")
	if err != nil {
		return xdr.SorobanAuthorizationEntry{}, err
	}
	d2, err := keypairFor("frozen-v0-1-0-delegates-d2")
	if err != nil {
		return xdr.SorobanAuthorizationEntry{}, err
	}

	credentials, err := addressCredentials(top.Address(), 7)
	if err != nil {
		return xdr.SorobanAuthorizationEntry{}, err
	}
	base, err := signedBase(xdr.SorobanCredentials{Type: xdr.SorobanCredentialsTypeSorobanCredentialsAddressV2, AddressV2: &credentials})
	if err != nil {
		return xdr.SorobanAuthorizationEntry{}, err
	}

	entry, err := soroauth.WithDelegates(base, validUntilLedger, []soroauth.Delegate{{
		Address: d1.Address(),
		Nested:  []soroauth.Delegate{{Address: d2.Address()}},
	}}, nil)
	if err != nil {
		return xdr.SorobanAuthorizationEntry{}, err
	}

	ctx := context.Background()
	entry, err = soroauth.AuthorizeEntry(ctx, entry, soroauth.NewEd25519Signer(top), validUntilLedger, network.TestNetworkPassphrase)
	if err != nil {
		return xdr.SorobanAuthorizationEntry{}, err
	}
	entry, err = soroauth.AuthorizeEntry(ctx, entry, soroauth.NewEd25519Signer(d1), validUntilLedger, network.TestNetworkPassphrase, soroauth.ForAddress(d1.Address()))
	if err != nil {
		return xdr.SorobanAuthorizationEntry{}, err
	}
	entry, err = soroauth.AuthorizeEntry(ctx, entry, soroauth.NewEd25519Signer(d2), validUntilLedger, network.TestNetworkPassphrase, soroauth.ForAddress(d2.Address()))
	if err != nil {
		return xdr.SorobanAuthorizationEntry{}, err
	}
	return entry, nil
}

// signedBase builds an unsigned address entry with an empty signature vector
// and the shared invocation tree.
func signedBase(credentials xdr.SorobanCredentials) (xdr.SorobanAuthorizationEntry, error) {
	invocation, err := invocation()
	if err != nil {
		return xdr.SorobanAuthorizationEntry{}, err
	}
	return xdr.SorobanAuthorizationEntry{
		Credentials:    credentials,
		RootInvocation: invocation,
	}, nil
}

func addressCredentials(address string, nonce int64) (xdr.SorobanAddressCredentials, error) {
	parsed, err := soroauth.ParseAddress(address)
	if err != nil {
		return xdr.SorobanAddressCredentials{}, fmt.Errorf("parsing %s: %w", address, err)
	}
	return xdr.SorobanAddressCredentials{
		Address:   parsed,
		Nonce:     xdr.Int64(nonce),
		Signature: xdr.ScVal{Type: xdr.ScValTypeScvVec, Vec: emptyVec()},
	}, nil
}

// invocation is a contract call with one sub-invocation, so Inspect's contract,
// function and sub-invocation fields are all exercised.
func invocation() (xdr.SorobanAuthorizedInvocation, error) {
	contract, err := contractAddress("frozen-v0-1-0-contract")
	if err != nil {
		return xdr.SorobanAuthorizedInvocation{}, err
	}
	sub, err := contractAddress("frozen-v0-1-0-subcontract")
	if err != nil {
		return xdr.SorobanAuthorizedInvocation{}, err
	}
	amount := xdr.Int64(100)
	return xdr.SorobanAuthorizedInvocation{
		Function: xdr.SorobanAuthorizedFunction{
			Type: xdr.SorobanAuthorizedFunctionTypeSorobanAuthorizedFunctionTypeContractFn,
			ContractFn: &xdr.InvokeContractArgs{
				ContractAddress: contract,
				FunctionName:    xdr.ScSymbol("transfer"),
				Args:            []xdr.ScVal{{Type: xdr.ScValTypeScvI64, I64: &amount}},
			},
		},
		SubInvocations: []xdr.SorobanAuthorizedInvocation{{
			Function: xdr.SorobanAuthorizedFunction{
				Type: xdr.SorobanAuthorizedFunctionTypeSorobanAuthorizedFunctionTypeContractFn,
				ContractFn: &xdr.InvokeContractArgs{
					ContractAddress: sub,
					FunctionName:    xdr.ScSymbol("approve"),
					Args:            []xdr.ScVal{},
				},
			},
		}},
	}, nil
}

func contractAddress(label string) (xdr.ScAddress, error) {
	sum := sha256.Sum256([]byte(label))
	encoded, err := strkey.Encode(strkey.VersionByteContract, sum[:])
	if err != nil {
		return xdr.ScAddress{}, err
	}
	return soroauth.ParseAddress(encoded)
}

// keypairFor derives a deterministic keypair from a label, the same scheme the
// benchmark and vector tests use, so regenerating produces identical bytes.
func keypairFor(label string) (*keypair.Full, error) {
	return keypair.FromRawSeed(sha256.Sum256([]byte(label)))
}

func emptyVec() **xdr.ScVec {
	vec := xdr.ScVec{}
	p := &vec
	return &p
}
